return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'German','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 17:31+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'de_DE','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Mehrsprachiges Routing, SEO-Meta-Tags und KI-Inhaltstools für WordPress. Kombiniert Spracherkennung, URL-Routing, hreflang, Meta-Beschreibungen sowie KI-gestützte Auszüge, Meta- und Übersetzungsfunktionen.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Übersetzen','Lingua Forge — Quick Translate'=>'Lingua Forge — Schnelles Übersetzen','Informative'=>'Informativ','Persuasive'=>'Überzeugend','Storytelling'=>'Storytelling','Technical'=>'Technisch','Conversational'=>'Gesprächig','Permission denied.'=>'Zugriff verweigert.','Cannot determine target language from slug.'=>'Ziel-Sprache kann aus dem Slug nicht bestimmt werden.','Invalid post type.'=>'Ungültiger Beitragstyp.','Invalid or primary language.'=>'Ungültige oder primäre Sprache.','Template not found or not stored in the database.'=>'Vorlage nicht gefunden oder nicht in der Datenbank gespeichert.','Template has no content.'=>'Vorlage hat keinen Inhalt.','No internal links found to update.'=>'Keine internen Links zum Aktualisieren gefunden.','%d link updated.'=>'%d Link aktualisiert.' . "\0" . '%d Links aktualisiert.','No language-specific template parts found to map.'=>'Keine sprachspezifischen Vorlage-Teile zum Abbilden gefunden.','No template part references needed updating.'=>'Keine Vorlage-Teile-Referenzen zum Aktualisieren erforderlich.','%d part reference updated.'=>'%d Teil-Referenz aktualisiert.' . "\0" . '%d Teil-Referenzen aktualisiert.','Invalid language.'=>'Ungültige Sprache.','Template part not found or not stored in the database.'=>'Vorlage-Teil nicht gefunden oder nicht in der Datenbank gespeichert.','Template part has no content.'=>'Vorlage-Teil hat keinen Inhalt.','No navigation references needed updating.'=>'Keine Navigationsreferenzen zum Aktualisieren erforderlich.','%d navigation reference updated.'=>'%d Navigationsreferenz aktualisiert.' . "\0" . '%d Navigationsreferenzen aktualisiert.','No AI provider configured.'=>'Kein KI-Anbieter konfiguriert.','Missing pattern name or language.'=>'Fehlender Mustername oder Sprache.','Pattern not found.'=>'Muster nicht gefunden.','Pattern has no content to translate.'=>'Muster hat keinen zu übersetzenden Inhalt.','AI provider returned an empty response.'=>'KI-Anbieter hat eine leere Antwort zurückgegeben.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Muster übersetzt und gespeichert. Kopiere den Inhalt in deinen CPT-Beitrag über den Block-Editor Muster-Insertor oder nutze es als Ausgangspunkt für einen wiederverwendbaren Block.','Invalid template type.'=>'Ungültiger Vorlage-Typ.','Template "%s" already exists.'=>'Vorlage "%s" existiert bereits.','"%s" created.'=>'"%s" erstellt.','Invalid template part.'=>'Ungültiger Vorlage-Teil.','Template part "%s" already exists.'=>'Vorlage-Teil "%s" existiert bereits.','"%1$s" created. %2$d template updated.'=>'"%1$s" erstellt. %2$d Vorlage aktualisiert.' . "\0" . '"%1$s" erstellt. %2$d Vorlagen aktualisiert.','Page'=>'Seite','Single'=>'Einzeln','Search'=>'Suche','Search Results'=>'Suchergebnisse','Archive'=>'Archiv','Front Page'=>'Startseite','Single: %s'=>'Einzeln: %s','Single %s'=>'Einzeln %s','Archive: %s'=>'Archiv: %s','%s Archive'=>'%s Archiv','No source content found to translate.'=>'Kein Quellinhalt zum Übersetzen gefunden.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Übersetzt. Überprüfe im Site Editor — interne Links, Navigations-URLs und Template-Slugs werden nicht automatisch aktualisiert.','Navigation not found.'=>'Navigation nicht gefunden.','Navigation has no content to translate.'=>'Navigation hat keinen Inhalt zum Übersetzen.','"%1$s %2$s" saved.'=>'"%1$s %2$s" gespeichert.','Translate page…'=>'Seite übersetzen…','Generate content…'=>'Inhalt generieren…','AI Behaviour Preset'=>'KI-Verhaltensvorgabe','Custom'=>'Benutzerdefiniert','Global default (%s)'=>'Globale Standardeinstellung (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Überschreibt die KI-Voreinstellung für Übersetzung und Inhaltserstellung auf dieser Seite. Site-weite benutzerdefinierte Anweisungen (Einstellungen → Verhalten) werden immer an jede Anfrage angehängt, unabhängig von dieser Auswahl.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Überschreibt die KI-Voreinstellung für Übersetzung und Inhaltserstellung auf dieser Seite. Alle anderen Funktionen verwenden immer die globale Voreinstellung.','Close'=>'Schließen','Translate missing'=>'Fehlende Übersetzung','From'=>'Von','Retranslate'=>'Erneut übersetzen','Translating…'=>'Übersetze…','Retranslating…'=>'Erneut übersetzen…','✓ Done'=>'✓ Fertig','Error'=>'Fehler','Navigation posts are translated via the Router tab, not this button.'=>'Navigation-Posts werden über den Router-Tab übersetzt, nicht über diese Schaltfläche.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Das Erstellen von Übersetzungen für den Beitragstyp "%s" erfordert eine aktive Integration. Bitte stelle sicher, dass die erforderliche Integration installiert und aktiviert ist.','No %s version found in this translation group.'=>'Keine %s-Version in dieser Übersetzungsgruppe gefunden.','AI Usage'=>'KI-Nutzung','Today'=>'Heute','Last 7 days'=>'Letzte 7 Tage','Last 30 days'=>'Letzte 30 Tage','All time'=>'Alle Zeiten','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Token-Verbrauch nach Funktion, Anbieter und Modell zusammengefasst. Aufgezeichnet bei jedem erfolgreichen KI-Aufruf; Testverbindungspings sind absichtlich ausgeschlossen, damit sie die Gesamtsumme nicht verfälschen. Die zugrunde liegende Tabelle aggregiert täglich — wähle unten ein Zeitfenster, um sie anzuzeigen.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Noch keine KI-Nutzung aufgezeichnet. Sobald ein Editor eine Übersetzung durchführt, eine Meta-Beschreibung generiert oder eine andere KI-Funktion nutzt, erscheinen hier die Gesamtsummen.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Keine KI-Nutzung im ausgewählten Zeitraum (%s) aufgezeichnet. Wähle oben einen größeren Zeitraum.','Feature'=>'Funktion','Provider'=>'Anbieter','Model'=>'Modell','Requests'=>'Anfragen','Input tokens'=>'Eingabe-Token','Output tokens'=>'Ausgabe-Token','Total tokens'=>'Gesamt-Token','Total'=>'Gesamt','API Keys'=>'API-Schlüssel','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Schlüssel werden vor der Speicherung in der WordPress-Datenbank mit AES-256-CBC verschlüsselt. Das Verschlüsselungsgeheimnis wird aus deinen WordPress-Auth-Salzen (wp-config.php) abgeleitet, sodass Klartext-Schlüssel die Datenbank nie berühren.','API Key'=>'API-Schlüssel','Paste your API key…'=>'Füge deinen API-Schlüssel ein…','✓ Configured'=>'✓ Konfiguriert','✗ Not configured'=>'✗ Nicht konfiguriert','Test connection'=>'Verbindung testen','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Lass es frei, um den bestehenden Schlüssel beizubehalten. Gib einen neuen Wert ein, um ihn zu ersetzen.','Remove stored key'=>'Gespeicherten Schlüssel entfernen','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Dieser Schlüssel wird derzeit von einem Server %s bereitgestellt und kann hier nicht entfernt werden. Gib oben einen neuen Schlüssel ein, um ihn mit einem Datenbankwert zu überschreiben.','environment variable'=>'Umweltvariable','PHP constant'=>'PHP-Konstante','Alternative (server-side):'=>'Alternativ (Server-seitig):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Du kannst Schlüssel auch als Konstanten oder Umweltvariablen definieren (z.B. in wp-config.php). Diese Quellen werden automatisch als Fallback verwendet, wenn kein Datenbankschlüssel gespeichert ist.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Um einen benutzerdefinierten Verschlüsselungsgeheimnis zu verwenden (anstatt des abgeleiteten wp_salt-Werts), füge dies in wp-config.php hinzu:','Unknown provider.'=>'Unbekannter Anbieter.','No API key configured for this provider.'=>'Für diesen Anbieter ist kein API-Schlüssel konfiguriert.','Could not instantiate the provider.'=>'Der Anbieter konnte nicht instanziiert werden.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Der Anbieter hat keinen Text zurückgegeben. Überprüfe das WordPress-Fehlerprotokoll für die detaillierte Fehlerursache.','Behavior'=>'Verhalten','Block Editor'=>'Block-Editor','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge beschränkt standardmäßig zwei Gutenberg-Funktionen, um das redaktionelle Verhalten in allen Sprachen konsistent zu halten. Hier kannst du dich anmelden, wenn du volle Gutenberg / FSE-Fähigkeiten benötigst.','Block locking'=>'Block-Sperre','Allow editors to lock individual blocks'=>'Erlaube Redakteuren, einzelne Blöcke zu sperren','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Aktiviert wieder Gutenberg\'s canLockBlocks. Nützlich für redaktionelle Vorlagen, die verhindern sollen, dass Mitwirkende bestimmte Blöcke verschieben oder löschen.','Template mode'=>'Vorlagenmodus','Allow Gutenberg template-editing mode on post screens'=>'Erlaube Gutenberg-Vorlagenbearbeitungsmodus auf Beitragsseiten','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Aktiviert supportsTemplateMode. Kern für Full-Site-Editing-Workflows, bei denen Beitragsübergreifende Vorlagenüberschreibungen beabsichtigt sind.','Compliance Preset'=>'Compliance-Voreinstellung','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strenger Erhaltungsmodus für rechtliche, regulatorische, medizinische oder technische Inhalte. Wenn aktiviert, verwendet jede KI-Funktion eine niedrige Abtasttemperatur und fügt die nachstehende Ergänzung an den Systemprompt an — Terminologie, Artikelnumer, Einheiten, Markennamen und regulatorische Sprache werden wortwörtlich beibehalten, anstatt umformuliert zu werden.','Global AI preset'=>'Globale KI-Voreinstellung','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, pro Funktion','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Legt das Standardverhalten der KI für alle Funktionen site-weit fest. Einzelne Beiträge können dies für Übersetzungen und Inhaltserstellung über die Meta-Box von Lingua Forge überschreiben.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard verwendet die eigene abgestimmte Temperatur jeder Funktion: Übersetzung T=0.2 (präzise), Schnelle Übersetzung T=0.4, Inhaltserstellung T=0.6 (kreativ). Die anderen Voreinstellungen verwenden eine einzelne feste Temperatur für alle Funktionen.','Technical / Scientific instructions'=>'Technische / Wissenschaftliche Anweisungen','Legal / Compliance instructions'=>'Rechtliche / Compliance-Anweisungen','Creative / Marketing instructions'=>'Kreative / Marketing-Anweisungen','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Lass es frei, um den integrierten Standard zu verwenden. Das Löschen einer gespeicherten Überschreibung stellt den Standard beim nächsten Speichern wieder her.','View built-in default'=>'Integrierten Standard anzeigen','Translation Memory'=>'Übersetzungsspeicher','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Übersetze die Äquivalente auf Blockebene zwischen, damit wiederverwendbare Inhalte (gemeinsame Fußzeilen, Seitenleisten, Akkordeons, rechtlich schwere Standardabschnitte) bei jedem API-Aufruf nicht erneut bezahlt werden müssen. Wenn aktiviert, zerlegt der Übersetzungsfluss jeden Beitrag in Blöcke, sucht jeden Block im Cache und sendet nur nicht gecachte Blöcke in einer einzigen Batch-Anfrage an die KI. Glossar-Änderungen und Änderungen an der Compliance-Voreinstellung invalidieren automatisch betroffene zwischengespeicherte Übersetzungen. Statistiken anzeigen und Cache unter Wartung löschen.','Enable block-level translation cache reuse across posts'=>'Blockebenen-Übersetzungscache-Wiederverwendung über Beiträge hinweg aktivieren','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Derzeit übersprungen für Beiträge, die Block-Kommentar-Attribut-Platzhalter verwenden (wp:details Zusammenfassungsfelder usw.) — sie fallen auf den bestehenden Einzel-Aufruf-Übersetzungsweg zurück.','General'=>'Allgemein','Light'=>'Leicht','Meta Description, Excerpt Generator'=>'Meta-Beschreibung, Exzerpt-Generator','Quality'=>'Qualität','Translation, Content Generator'=>'Übersetzung, Inhaltserstellung','Active Provider'=>'Aktueller Anbieter','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Derzeit geerbt vom %s-Konstanten. Die Auswahl eines Werts hier überschreibt ihn.','Models'=>'Modelle','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funktionen sind in zwei Ebenen gruppiert. Gib die genaue Modellkennung für jede Ebene und jeden Anbieter ein. Lasse ein Feld leer, um den integrierten Standard zu verwenden (als Platzhalter angezeigt). Nur die aktiven Anbieter-Modelle werden zur Laufzeit aufgerufen — konfiguriere die anderen im Voraus, wenn du planst zu wechseln.','active'=>'aktiv','overridden'=>'überschrieben','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tipp: Um ein Modell auf den integrierten Standard zurückzusetzen, lösche das Feld und speichere.','Glossary'=>'Glossar','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Benutzerverwaltete Terminologietabelle pro Sprachpaar. Einträge werden an den Übersetzungssystemprompt angehängt, damit die KI bevorzugte Begriffe konsequent verwendet – entscheidend für Fachvokabular ("kWp", "PPA", "Anschlussstelle"), Markennamen, die nicht übersetzt werden dürfen, und standardisierte regulatorische Formulierungen. Beide Sprachfelder sind optional: Lass "Quellsprache" leer, um den Eintrag unabhängig von der Sprache, aus der du übersetzt, anzuwenden; lass "Zielsprache" leer, um ihn auf alle Zielsprache gleichzeitig anzuwenden.','Glossary entry added.'=>'Glossareintrag hinzugefügt.','Glossary entry removed.'=>'Glossareintrag entfernt.','Could not add entry: source term and target term are required.'=>'Eintrag konnte nicht hinzugefügt werden: Quell- und Zielbegriff sind erforderlich.','Could not save the glossary entry.'=>'Das Glossareintrag konnte nicht gespeichert werden.','Source language'=>'Quellsprache','— Any —'=>'— Beliebig —','Target language'=>'Zielsprache','— Any target —'=>'— Beliebige Zielsprache —','Filter'=>'Filter','Reset'=>'Zurücksetzen','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Keine Glossareinträge entsprechen dem aktuellen Filter. Entferne den Filter, um alle Einträge zu sehen, oder füge unten einen neuen Eintrag hinzu.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Noch keine Glossareinträge. Füge unten einen hinzu, um die Terminologie in Übersetzungen durchzusetzen.','Source term'=>'Quellbegriff','Target term'=>'Zielbegriff','Source lang'=>'Quell-Sprache','Target lang'=>'Ziel-Sprache','Notes'=>'Notizen','any'=>'beliebig','Delete this glossary entry?'=>'Diesen Glossareintrag löschen?','Delete'=>'Löschen','Add new entry'=>'Neuen Eintrag hinzufügen','The phrase as it appears in the source text.'=>'Der Ausdruck, wie er im Quelltext erscheint.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'So soll er in der Übersetzung erscheinen. Gib denselben Wert wie den Quellbegriff ein, um die KI anzuweisen, ihn wortwörtlich zu bewahren.','— Any source language —'=>'— Beliebige Quellsprache —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Lass es leer für Markennamen und sprachunabhängige Begriffe, die unabhängig von der Sprache, aus der wir übersetzen, durchgesetzt werden sollen.','— Any target language —'=>'— Beliebige Zielsprache —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Lass es leer, um diesen Eintrag auf alle Zielsprache anzuwenden – ideal für Markennamen, Abkürzungen und Begriffe, die in jeder Übersetzung wortwörtlich erhalten bleiben müssen.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Optionaler Kontext für Redakteure (z.B. "ASIC = Application-Specific Integrated Circuit; in technischen Kontexten auf Englisch belassen").','Add entry'=>'Eintrag hinzufügen','Limits'=>'Grenzen','Authors and above (edit_published_posts)'=>'Autoren und höher (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Mitwirkende und höher – Standard (edit_posts)','Editors and above (edit_others_posts)'=>'Redakteure und höher (edit_others_posts)','Administrators only (manage_options)'=>'Nur Administratoren (manage_options)','AI Limits & Security'=>'KI-Grenzen & Sicherheit','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Begrenze die Nutzung der KI auf der Seite und beschränke, welche Benutzerrollen kostenpflichtige KI-Anfragen auslösen dürfen. Überlagert die pro-Benutzer-Grenze (30 Anfragen / Minute, fest codiert), die bereits vor unkontrollierten Schleifen schützt.','Daily request limit'=>'Tägliches Anfrage-Limit','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Gesamtgrenze für KI-Anfragen pro UTC-Tag (zählt sowohl Toolbar-Übersetzungen als auch Block-Revisionen). Zählt bei UTC-Midnight zurück. Setze auf 0, um die Begrenzung zu deaktivieren.','Minimum role'=>'Mindestrolle','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Niedrigste WordPress-Fähigkeit, die zum Auslösen von KI-Funktionen erlaubt ist. Das Verschärfen auf Multi-Autor-Websites verhindert, dass Mitwirkende oder Testkonten kostenpflichtige KI-Anfragen ausführen. Überschreibe pro Funktion via den linguaforge_required_capability-Filter.','Translation Limits'=>'Übersetzungsbegrenzungen','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Steuere, wie viel Inhalt an die KI gesendet wird und wie groß die Antwort sein darf. Lass ein Feld leer, um den integrierten Standard zu verwenden (als Platzhalter angezeigt). Erhöhe diese Werte, wenn große Seiten abgeschnitten werden; senke sie, um API-Kosten zu reduzieren.','Model tier'=>'Modellstufe','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualität (Standard – Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Licht (schnell und kosteneffizient – Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Welche Modellstufe für die Vollseitenübersetzung verwenden. Qualität nutzt das im obigen Modelle-Tabelle konfigurierte Modell und wird für genaue, längere Übersetzungen empfohlen. Wechsle nur zu Licht, wenn Geschwindigkeit oder Kosten Priorität haben und der Inhalt kurz ist.','Max output tokens'=>'Maximale Ausgaben-Tokens','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximale Anzahl an Tokens, die die KI in einer einzigen Übersetzungsantwort produzieren darf. Wenn eine Übersetzung am Ende stillschweigend abgeschnitten wird, erhöhe diesen Wert. Standard: 16.000.','Max input characters'=>'Maximale Eingabebuchstaben','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximale Anzahl der Zeichen des Beitragsinhalts, die an die KI weitergeleitet werden. 0 bedeutet kein Limit – der vollständige Inhalt wird immer gesendet (empfohlen). Stelle nur einen nicht-null Wert ein, wenn dein Anbieter ein enges Kontextfenster hat. Eine Warnung wird in das PHP-Fehlerprotokoll geschrieben, wenn der Inhalt gekürzt wird.','Quick Translation'=>'Schnelle Übersetzung','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Schnelle Übersetzung wird im Snippet-/Chunk-Modus verwendet – kurze Passagen, die auf Abruf aus der Symbolleiste, dem Editor oder den Block-Popovers übersetzt werden. Es verwendet eine separate, leichtere Konfiguration als die Vollseitenübersetzung, um schnelle und kostengünstige Antworten zu gewährleisten.','Light (default — fast and cost-effective)'=>'Light (Standard – schnell und kostengünstig)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualität (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Die Light-Stufe verwendet das schnelle Modell, das in der oben stehenden Modellauswahl konfiguriert ist (Standard: Haiku / Flash). Wechsle zu Qualität, wenn du die gleiche Übersetzungsgenauigkeit wie im Vollseitenmodus für Snippets benötigst.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximale Tokens, die die KI pro schnelle Übersetzung produzieren darf. Standard: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximale akzeptierte Zeichen vom Eingabefeld. Standard: 8.000.','Content Generator'=>'Content-Generator','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Steuert das Token-Budget und die Eingabebegrenzungen für die Funktion des KI-Content-Generators. Lasse die Felder leer, um die integrierten Standardwerte zu verwenden.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximale Tokens, die die KI pro Generationslauf produzieren darf. Erhöhe dies, wenn vollständige Artikel abgeschnitten werden. Standard: 8.192.','Max hints characters'=>'Max. Hinweise-Zeichen','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximale Zeichen, die aus dem Hinweise-Feld gelesen werden. Standard: 2.000.','Max context characters'=>'Max. Kontextzeichen','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximale Zeichen des bestehenden Beitragsinhalts, die an die KI als Saatkontext übergeben werden, wenn keine Hinweise bereitgestellt werden. Standard: 6.000.','Maintenance'=>'Wartung','Language Overrides'=>'Sprachüberschreibungen','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Kompilierte .mo-Dateien hochladen, um Strings von Drittanbieter-Plugins für bestimmte Sprachen zu überschreiben – zum Beispiel eine benutzerdefinierte VikBooking-Übersetzung, die "Apartment" anstelle von "Zimmer" verwendet. Dateien müssen dem WordPress-Namensschema folgen: {textdomain}-{locale}.mo (z.B. vikbooking-ca.mo). Sie werden im Upload-Ordner gespeichert und überleben Plugin-Updates.','Override file uploaded successfully.'=>'Überschreibungsdatei erfolgreich hochgeladen.','Override file deleted.'=>'Überschreibungsdatei gelöscht.','No file was selected.'=>'Keine Datei ausgewählt.','Only .mo files are accepted.'=>'Nur .mo-Dateien werden akzeptiert.','The upload failed — please try again.'=>'Der Upload ist fehlgeschlagen – bitte versuche es erneut.','Could not save the file. Check that the uploads folder is writable.'=>'Datei konnte nicht gespeichert werden. Überprüfe, ob der Upload-Ordner beschreibbar ist.','Invalid filename.'=>'Ungültiger Dateiname.','Security check failed — file path is not permitted.'=>'Sicherheitsüberprüfung fehlgeschlagen – Dateipfad ist nicht erlaubt.','An unknown error occurred.'=>'Ein unbekannter Fehler ist aufgetreten.','Text domain / locale'=>'Textdomain / Sprache','Files'=>'Dateien','Size'=>'Größe','Delete all files for this override (both .mo and .po)?'=>'Alle Dateien für diese Überschreibung löschen (sowohl .mo- als auch .po-Dateien)?','No override files uploaded yet.'=>'Noch keine Überschreibungsdateien hochgeladen.','Upload .mo file'=>'.mo-Datei hochladen','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Akzeptiert nur kompilierte .mo-Dateien. Der Dateiname muss dem Muster {textdomain}-{locale}.mo folgen. Das Hochladen einer Datei mit demselben Namen wie eine bestehende ersetzt sie.','Upload Override'=>'Überschreibung hochladen','Loco Translate — Copy to Safe Storage'=>'Loco Translate – In sicheren Speicher kopieren','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate speichert seine benutzerdefinierten Übersetzungen im Verzeichnis wp-content/languages/loco/ – ein Ort, der bei einem WP-Kern-Update, Plugin-Neuinstallation oder bei Entfernung von Loco Translate still gelöscht werden kann. Das Kopieren der Dateien hier verschiebt sie in das Lingua Forge i18n-overrides-Verzeichnis, das all diesen Ereignissen standhält und bei jeder Anfrage automatisch geladen wird.','File copied to safe storage successfully.'=>'Datei erfolgreich in sicheren Speicher kopiert.','Source file not found.'=>'Quelldatei nicht gefunden.','Could not copy the file. Check that the uploads folder is writable.'=>'Datei konnte nicht kopiert werden. Überprüfe, ob der Upload-Ordner beschreibbar ist.','Invalid file reference.'=>'Ungültige Dateireferenz.','Type'=>'Typ','✓ In safe storage'=>'✓ Im sicheren Speicher','Copy to safe storage'=>'In sicheren Speicher kopieren','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Noch keine benutzerdefinierten Loco Translate-Dateien gefunden. Sie erscheinen hier, sobald du eine Übersetzung in Loco Translate speicherst.','AI Cache'=>'KI-Cache','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge cached KI-generierte Übersetzungen, Meta-Beschreibungen, Auszüge und generierte Inhalte pro Beitrag, sodass unveränderte Eingaben keine kostenpflichtige API-Anfrage auslösen. Cache-Einträge werden automatisch ungültig, wenn sich ihre Eingaben ändern. Lösche den Cache manuell, um Datenbankplatz freizugeben, nach Anbieterwechsel oder Bearbeitung von Prompt-Vorlagen eine Synchronisation zu erzwingen oder bei einem cachebezogenen Problem.','AI cache cleared. %d entry was removed.'=>'KI-Cache gelöscht. %d Eintrag wurde entfernt.' . "\0" . 'KI-Cache gelöscht. %d Einträge wurden entfernt.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Alle zwischengespeicherten KI-Ergebnisse löschen? Zukünftige Anfragen lösen neue API-Aufrufe aus, bis der Cache neu aufgebaut ist.','Clear AI Cache'=>'AI-Cache löschen','Debug Files'=>'Debug-Dateien','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wenn das Debug-Logging aktiviert ist (über den Schalter unten oder durch die Definition von LINGUAFORGE_AI_DEBUG in wp-config.php), schreiben die Übersetzungs- und FSE-Template-Übersetzungsfunktionen ihre rohen AI-Aufforderungen und Antworten zur Fehlerbehebung auf die Festplatte. Nutze diesen Abschnitt, um diese Ausgabe zu überwachen und sie zu löschen, sobald du hast, was du brauchst — die Dateien können bei großen Seiten schnell wachsen. Konfiguriere das Zielverzeichnis über den linguaforge_debug_dir-Filter.','Debug files cleared. %d file was removed.'=>'Debug-Datei gelöscht. %d Datei wurde entfernt.' . "\0" . 'Debug-Dateien gelöscht. %d Dateien wurden entfernt.','Debug logging enabled.'=>'Debug-Logging aktiviert.','Debug logging disabled.'=>'Debug-Logging deaktiviert.','Debug logging'=>'Debug-Logging','Write AI prompts and responses to disk for troubleshooting'=>'AI-Aufforderungen und Antworten zur Fehlerbehebung auf die Festplatte schreiben','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Erzwungen EIN durch die Konstante LINGUAFORGE_AI_DEBUG in wp-config.php. Entferne diese Zeile, um diesen Schalter von hier aus zu steuern.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Erzwungen AUS durch die Konstante LINGUAFORGE_AI_DEBUG in wp-config.php. Entferne diese Zeile, um diesen Schalter von hier aus zu steuern.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Dateien landen im unten stehenden Verzeichnis. Nützlich zur Diagnose von Übersetzungsproblemen — schalte es aus, sobald du hast, was du brauchst, damit die Dateien sich nicht anhäufen. Du kannst dies auch in wp-config.php erzwingen mit `define( \'LINGUAFORGE_AI_DEBUG\', true );`, was den Schalter überschreibt.','Currently:'=>'Derzeit:','✓ Enabled'=>'✓ Aktiviert','✗ Disabled'=>'✗ Deaktiviert','Directory'=>'Verzeichnis','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Mit linguaforge_debug_dir filtern, um Debug-Ausgaben an einen nicht-öffentlichen Ort umzuleiten.','.txt file(s) in the directory'=>'.txt-Datei(en) im Verzeichnis','Save Debug Setting'=>'Debug-Einstellung speichern','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Alle .txt-Dateien im Debug-Verzeichnis löschen? Das Verzeichnis selbst bleibt erhalten, damit zukünftige Debug-Schreibvorgänge weiterhin sauber landen.','Clear Debug Files'=>'Debug-Dateien löschen','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Pro-Block-Übersetzungscache, der über Beiträge hinweg geteilt wird. In den Einstellungen → Verhalten konfigurieren. Die unten stehenden Statistiken zeigen, was derzeit zwischengespeichert ist; das Löschen erzwingt, dass jeder Block bei der nächsten Anfrage neu übersetzt wird (nützlich nach Modell-Updates oder um Datenbankplatz freizugeben).','Translation Memory cleared. %d cached block was removed.'=>'Übersetzungsspeicher gelöscht. %d zwischengespeicherter Block wurde entfernt.' . "\0" . 'Übersetzungsspeicher gelöscht. %d zwischengespeicherte Blöcke wurden entfernt.','Status'=>'Status','— toggle in Settings → Behavior.'=>'— Schalter in Einstellungen → Verhalten.','Cached blocks'=>'Zwischengespeicherte Blöcke','Cumulative cache hits'=>'Kumulative Cache-Hits','(avg %.1f hits/block)'=>'(ø %.1f Treffer/Block)','Oldest entry'=>'Ältester Eintrag','Newest entry'=>'Neuster Eintrag','Approximate size'=>'Ungefähre Größe','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Gesamten Übersetzungsspeicher löschen? Zukünftige Übersetzungen bauen den Cache beim Ausführen neu auf.','Clear Translation Memory'=>'Übersetzungsspeicher löschen','Uninstall Behaviour'=>'Deinstallationsverhalten','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Steuert, was passiert, wenn ein Administrator das Plugin in Plugins → Installierte Plugins → Löschen entfernt. Plugin-Einstellungen und AI-Caches werden immer entfernt. Sprachzuweisungen und Übersetzungsbeziehungen bleiben standardmäßig erhalten, damit eine versehentliche Deinstallation oder Neuinstallation dort anknüpfen kann, wo sie aufgehört hat.','Uninstall setting saved.'=>'Deinstallations-Einstellung gespeichert.','Delete content data on uninstall'=>'Inhalt bei Deinstallation löschen','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Auch Sprachzuweisungen, Übersetzungsbeziehungen, Meta-Beschreibungen, Glossar und Übersetzungsspeicher löschen, wenn das Plugin deinstalliert wird.','Warning:'=>'Warnung:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Wenn aktiviert, werden bei der Deinstallation alle Sprachzuweisungen, Übersetzungsbeziehungen, Meta-Beschreibungen, Seiten-Voreinstellungen, das AI-Glossar und der Übersetzungsspeicher für jede Seite auf dieser Seite dauerhaft gelöscht. Dies kann nicht rückgängig gemacht werden. Nicht aktivieren, wenn du den mehrsprachigen Support vollständig entfernen möchtest.','Save Uninstall Setting'=>'Deinstallations-Einstellung speichern','Router'=>'Router','Primary language saved.'=>'Primärsprache gespeichert.','Permalink rules flushed successfully.'=>'Permalink-Regeln erfolgreich gelöscht.','Primary Language'=>'Primärsprache','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Die primäre Sprache wird immer an der Wurzel deiner Seite bedient — kein URL-Präfix im Pfadmodus, keine Sprach-Subdomain im Subdomain-Modus. Alle anderen Sprachen verwenden entweder ein /lang/ Pfadpräfix (z.B. example.com/de/) oder eine Sprach-Subdomain (z.B. de.example.com), abhängig von der unten stehenden URL-Struktur-Einstellung.','Primary language'=>'Primärsprache','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Nach Änderung der primären Sprache die Permalinks (Abschnitt unten) aktualisieren, damit die URL-Routing-Änderungen wirksam werden.','URL structure'=>'URL-Struktur','Path prefix — example.com/de/'=>'Pfadpräfix — example.com/de/','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Der Subdomain-Modus erfordert, dass dein Webserver alle Sprach-Subdomains (z.B. de.example.com) auf diese WordPress-Installation zeigt. Nach dem Wechsel des Modus, leere die Permalink-Regeln und lösche alle Caches. Wenn deine Start-URL www enthält (z.B. www.example.com), verwende den lf_base_domain Filter, um die reine Domain festzulegen, damit die Subdomains korrekt aufgebaut werden.','Browser language redirect'=>'Browser-Sprachumleitung','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Leite Besucher basierend auf dem Accept-Language-Header ihres Browsers auf ihre bevorzugte Sprache um','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wenn aktiviert, werden Erstbesucher ohne Sprach-Cookie und ohne Sprachpräfix in der URL auf die nächstgelegene passende Sprachversion umgeleitet. Die Umleitung wird übersprungen, wenn die bevorzugte Sprache des Browsers nicht zu den aktiven Router-Sprachen gehört. Sobald ein Besucher eine Sprache über den Schalter auswählt, hat das Cookie Vorrang und der Browser-Header wird bei zukünftigen Besuchen ignoriert.','Save Router Settings'=>'Router-Einstellungen speichern','Flush Permalinks'=>'Permalinks leeren','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regeneriert die Rewrite-Regeln von WordPress, sodass URL-Präfixe, sprachspezifische Slugs und Archiv-Umleitungen synchron sind. Notwendig nach Änderung der Primärsprache oder Hinzufügen neuer Sprachunterstützung.','Flush Permalink Rules'=>'Permalink-Regeln leeren','Active Languages'=>'Aktive Sprachen','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Sprachen, die dem Router derzeit bekannt sind (abgeleitet von installierten WordPress-Lokalisierungspaketen plus der Primärsprache). Installiere zusätzliche Sprachpakete im unteren Abschnitt, um mehr Sprachen für Routing und Übersetzung verfügbar zu machen.','%d locale pack installed.'=>'%d Lokalisierungspaket installiert.' . "\0" . '%d Lokalisierungspakete installiert.','Install a Language'=>'Eine Sprache installieren','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Lade und installiere ein WordPress-Kern-Lokalisierungspaket direkt von WordPress.org. Nach der Installation steht die Lokalisierung für URL-Routing und den KI-Übersetzungsworkflow zur Verfügung. Die Liste der verfügbaren Sprachen wird bei Bedarf abgerufen — klicke auf die Schaltfläche unten, um sie zu laden.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Die Sprachinstallation ist auf diesem Server deaktiviert. Die Konstante DISALLOW_FILE_MODS ist in wp-config.php gesetzt. Installiere Sprachpakete manuell via WP-CLI: wp language core install de_DE','Load available languages'=>'Verfügbare Sprachen laden','— select a language —'=>'— wähle eine Sprache —','Install'=>'Installieren','Language Setup'=>'Sprachsetup','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Keine sekundären Sprachen konfiguriert. Installiere ein Sprachpaket oben, um die Vorlagenerstellung zu aktivieren.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Wähle eine Sprache, um ihre FSE-Vorlagen, Vorlage-Teile und Navigationsmenüs zu verwalten.','Forbidden'=>'Verboten','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Die Sprachinstallation ist auf diesem Server deaktiviert (DISALLOW_FILE_MODS ist gesetzt).','Invalid locale code.'=>'Ungültiger Lokalisierungscode.','Language %s installed successfully.'=>'Sprache %s erfolgreich installiert.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Die Installation des Sprachpakets ist fehlgeschlagen. Die Sprache ist möglicherweise bereits installiert, der Lokalisierungscode ist falsch oder dein Server blockiert Dateischreibrechte.','Navigations'=>'Navigationen','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Navigation-Übersetzung erfordert einen aktiven KI-Anbieter. Konfiguriere einen API-Schlüssel im Tab API-Schlüssel.','Navigation'=>'Navigation','Action'=>'Aktion','Re-translate'=>'Neu übersetzen','CPT Block Patterns'=>'CPT-Blockmuster','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Blockmuster, die für benutzerdefinierte Beitragstypen registriert sind. Verwende die Übersetzen-Schaltfläche, um eine Sprachvariante zu erstellen. Der übersetzte Inhalt wird hier gespeichert und kann vom Block-Editor Pattern-Inserter in jeden CPT-Beitrag kopiert oder als Ausgangspunkt für ein synchronisiertes Muster (Wiederverwendeter Block) verwendet werden.','Pattern'=>'Muster','Post Types'=>'Beitragstypen','✓ Translation saved'=>'✓ Übersetzung gespeichert','View'=>'Ansicht','Template Parts'=>'Vorlagen-Teile','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Sprachspezifische Kopien der Vorlagen-Teile des Themes. Nach der Erstellung werden die Vorlagen aktualisiert, um auf den sprachspezifischen Teil zu verweisen.','Part'=>'Teil','Status / Actions'=>'Status / Aktionen','Fix Links'=>'Links reparieren','Fix Nav'=>'Navigation reparieren','Create'=>'Erstellen','Templates'=>'Vorlagen','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'FSE-Vorlagen, die vom aktiven Theme vorgegeben sind. Erstelle sie und passe sie im Site Editor an.','Actions'=>'Aktionen','Fix Parts'=>'Teile reparieren','Create missing'=>'Erstellen, was fehlt','Translate all'=>'Alles übersetzen','Fix all parts'=>'Alle Teile reparieren','Fix all links'=>'Alle Links reparieren','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Wird getestet…','✓ Connection OK'=>'✓ Verbindung OK','✗ Failed:'=>'✗ Fehler: ','No response from provider — check the error log for details.'=>'Keine Antwort vom Anbieter — Überprüfe das Fehlerprotokoll für Details.','Network error — could not reach the WordPress AJAX endpoint.'=>'Netzwerkfehler — konnte die WordPress AJAX-Schnittstelle nicht erreichen.','Loading…'=>'Lädt…','Installing…'=>'Installiert…','✓ Language installed.'=>'✓ Sprache installiert.','✗ Error:'=>'✗ Fehler:','Creating…'=>'Wird erstellt…','✓ All templates created.'=>'✓ Alle Vorlagen erstellt.','Some templates could not be created.'=>'Einige Vorlagen konnten nicht erstellt werden.','✓ All parts created.'=>'✓ Alle Teile erstellt.','Some parts could not be created.'=>'Einige Teile konnten nicht erstellt werden.','✓ All translated.'=>'✓ Alle übersetzt.','Some translations failed.'=>'Einige Übersetzungen sind fehlgeschlagen.','Review carefully — links and slugs not updated.'=>'Überprüfe sorgfältig — Links und Slugs wurden nicht aktualisiert.','Fixing…'=>'Wird repariert…','✓ Links fixed.'=>'✓ Links repariert.','Some link fixes failed.'=>'Einige Link-Reparaturen sind fehlgeschlagen.','✓ Parts fixed.'=>'✓ Teile repariert.','Some part fixes failed.'=>'Einige Teile-Reparaturen sind fehlgeschlagen.','✓ Nav refs fixed.'=>'✓ Navigationsreferenzen repariert.','Some nav ref fixes failed.'=>'Einige Navigationsreferenz-Reparaturen sind fehlgeschlagen.','✓ Pattern translated.'=>'✓ Muster übersetzt.','Pattern translation failed.'=>'Musterübersetzung fehlgeschlagen.','Hide'=>'Verbergen','Built-in preset instructions:'=>'Integrierte Voreinstellungen: ','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Keine integrierten Anweisungen — jede KI-Funktion verwendet ih